#!/usr/bin/env node
/**
 * RockSEO Script 6 — Content Consolidation Helper
 * 
 * Purpose:
 * - Reads SERP overlap report
 * - Groups overlapping pages by topic
 * - Recommends merge/delete/differentiate actions
 * - Generates consolidated content structure
 * 
 * Usage: node rockseo/consolidate-content.mjs
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.join(__dirname, "..");

const CONFIG = {
    overlapReport: path.join(__dirname, "reports/serp-overlap-report.json"),
    outputReport: path.join(__dirname, "reports/consolidation-plan.json"),
    outputText: path.join(__dirname, "reports/consolidation-plan.txt"),

    // Similarity threshold for grouping
    groupThreshold: 70,

    // Priority topics (keep the canonical page)
    canonicalPaths: {
        "gum": "/services/gum-treatment",
        "implant": "/services/dental-implants",
        "root canal": "/services/root-canal-treatment",
        "orthodontic": "/services/orthodontics",
        "braces": "/services/orthodontics",
        "whitening": "/services/cosmetic-dentistry/teeth-whitening",
        "crown": "/services/restorative-dentistry/dental-crowns",
        "extraction": "/services/oral-surgery/tooth-extraction",
        "emergency": "/services/emergency-dentistry",
        "filling": "/services/restorative-dentistry/dental-fillings"
    }
};

const results = {
    timestamp: new Date().toISOString(),
    totalOverlaps: 0,
    groupsIdentified: 0,
    mergeRecommendations: [],
    deleteRecommendations: [],
    differentiateRecommendations: [],
    consolidationGroups: []
};

/**
 * Group overlapping pages by similarity
 */
function groupOverlaps(overlaps) {
    const groups = new Map();

    for (const overlap of overlaps) {
        // Create a group key based on the pages
        const key1 = overlap.page1;
        const key2 = overlap.page2;

        // Find existing group or create new
        let foundGroup = null;
        for (const [groupId, group] of groups) {
            if (group.pages.has(key1) || group.pages.has(key2)) {
                foundGroup = groupId;
                break;
            }
        }

        if (foundGroup) {
            groups.get(foundGroup).pages.add(key1);
            groups.get(foundGroup).pages.add(key2);
            groups.get(foundGroup).overlaps.push(overlap);
        } else {
            const groupId = `group-${groups.size + 1}`;
            groups.set(groupId, {
                pages: new Set([key1, key2]),
                overlaps: [overlap],
                topic: overlap.topic,
                maxSimilarity: overlap.similarity
            });
        }
    }

    // Convert to array and sort by size
    return Array.from(groups.values())
        .map(g => ({
            ...g,
            pages: Array.from(g.pages),
            pageCount: g.pages.size
        }))
        .sort((a, b) => b.pageCount - a.pageCount);
}

/**
 * Determine canonical page for a group
 */
function findCanonicalPage(pages, topic) {
    // Check if any page is a service/condition page (not blog)
    const servicePage = pages.find(p =>
        p.startsWith("/services/") || p.startsWith("/conditions/")
    );
    if (servicePage) return servicePage;

    // Check canonical paths
    for (const [keyword, canonical] of Object.entries(CONFIG.canonicalPaths)) {
        if (topic && topic.includes(keyword)) {
            const match = pages.find(p => p === canonical);
            if (match) return match;
        }
    }

    // Prefer shorter slugs (more general)
    const sorted = [...pages].sort((a, b) => a.length - b.length);
    return sorted[0];
}

/**
 * Generate action recommendation
 */
function generateRecommendation(group) {
    const { pages, topic, maxSimilarity, pageCount } = group;

    const canonical = findCanonicalPage(pages, topic);
    const others = pages.filter(p => p !== canonical);

    // Determine action based on similarity and page types
    let action = "DIFFERENTIATE";
    let reason = "";

    if (maxSimilarity >= 85) {
        // Very high similarity - likely duplicates
        const allBlogs = pages.every(p => p.startsWith("/blog/"));
        if (allBlogs) {
            action = "MERGE";
            reason = `${pageCount} blog posts cover same topic. Merge into comprehensive guide.`;
        } else {
            action = "REDIRECT";
            reason = `High overlap (${maxSimilarity}%). Redirect weaker pages to ${canonical}`;
        }
    } else if (maxSimilarity >= 70) {
        action = "DIFFERENTIATE";
        reason = `Moderate overlap (${maxSimilarity}%). Add unique angles to each page.`;
    } else {
        action = "MONITOR";
        reason = `Lower overlap (${maxSimilarity}%). Monitor for ranking competition.`;
    }

    return {
        action,
        reason,
        canonical,
        pagesToConsolidate: others,
        totalPages: pageCount,
        topic,
        similarity: maxSimilarity
    };
}

/**
 * Main execution
 */
async function main() {
    console.log("📋 RockSEO Content Consolidation Helper");
    console.log("=".repeat(55));

    // Load overlap report
    if (!fs.existsSync(CONFIG.overlapReport)) {
        console.error("❌ Overlap report not found. Run serp-overlap-detector.mjs first.");
        process.exit(1);
    }

    const report = JSON.parse(fs.readFileSync(CONFIG.overlapReport, "utf8"));

    console.log(`\n📊 Loaded overlap report:`);
    console.log(`   High overlaps: ${report.highOverlaps.length}`);
    console.log(`   Medium overlaps: ${report.mediumOverlaps.length}`);

    results.totalOverlaps = report.highOverlaps.length + report.mediumOverlaps.length;

    // Group high-priority overlaps
    console.log("\n🔄 Grouping overlapping pages...");

    const highGroups = groupOverlaps(report.highOverlaps);

    console.log(`   Groups identified: ${highGroups.length}`);
    results.groupsIdentified = highGroups.length;

    // Generate recommendations for top groups
    console.log("\n📝 Generating consolidation recommendations...\n");

    const topGroups = highGroups.slice(0, 50); // Focus on top 50 groups

    for (const group of topGroups) {
        const recommendation = generateRecommendation(group);

        results.consolidationGroups.push({
            ...recommendation,
            allPages: group.pages
        });

        // Categorize
        if (recommendation.action === "MERGE") {
            results.mergeRecommendations.push(recommendation);
        } else if (recommendation.action === "REDIRECT") {
            results.deleteRecommendations.push(recommendation);
        } else {
            results.differentiateRecommendations.push(recommendation);
        }
    }

    // Generate text report
    let textReport = `CONTENT CONSOLIDATION PLAN\n`;
    textReport += `Generated: ${new Date().toISOString()}\n`;
    textReport += "=".repeat(60) + "\n\n";

    textReport += `SUMMARY\n`;
    textReport += `-`.repeat(40) + "\n";
    textReport += `Total overlaps analyzed: ${results.totalOverlaps}\n`;
    textReport += `Groups identified: ${results.groupsIdentified}\n`;
    textReport += `Merge recommendations: ${results.mergeRecommendations.length}\n`;
    textReport += `Redirect recommendations: ${results.deleteRecommendations.length}\n`;
    textReport += `Differentiate recommendations: ${results.differentiateRecommendations.length}\n\n`;

    // Merge recommendations
    if (results.mergeRecommendations.length > 0) {
        textReport += `\n🔀 MERGE THESE PAGES\n`;
        textReport += `(Combine into single comprehensive guide)\n`;
        textReport += "-".repeat(40) + "\n\n";

        for (const rec of results.mergeRecommendations.slice(0, 20)) {
            textReport += `Topic: ${rec.topic || "Mixed"}\n`;
            textReport += `Canonical: ${rec.canonical}\n`;
            textReport += `Merge from: ${rec.pagesToConsolidate.slice(0, 5).join(", ")}\n`;
            if (rec.pagesToConsolidate.length > 5) {
                textReport += `           ... and ${rec.pagesToConsolidate.length - 5} more\n`;
            }
            textReport += `Reason: ${rec.reason}\n\n`;
        }
    }

    // Redirect recommendations
    if (results.deleteRecommendations.length > 0) {
        textReport += `\n🔄 REDIRECT THESE PAGES\n`;
        textReport += `(301 redirect to canonical page)\n`;
        textReport += "-".repeat(40) + "\n\n";

        for (const rec of results.deleteRecommendations.slice(0, 10)) {
            textReport += `Redirect TO: ${rec.canonical}\n`;
            textReport += `Redirect FROM:\n`;
            for (const page of rec.pagesToConsolidate.slice(0, 5)) {
                textReport += `  - ${page}\n`;
            }
            textReport += `Reason: ${rec.reason}\n\n`;
        }
    }

    // Differentiate recommendations
    textReport += `\n✏️ DIFFERENTIATE THESE PAGES\n`;
    textReport += `(Add unique value to each)\n`;
    textReport += "-".repeat(40) + "\n\n";

    for (const rec of results.differentiateRecommendations.slice(0, 10)) {
        textReport += `Topic: ${rec.topic || "Mixed"} (${rec.similarity}% similar)\n`;
        textReport += `Pages:\n`;
        for (const page of rec.allPages?.slice(0, 5) || []) {
            textReport += `  - ${page}\n`;
        }
        textReport += `Action: ${rec.reason}\n\n`;
    }

    // Save reports
    fs.writeFileSync(CONFIG.outputReport, JSON.stringify(results, null, 2));
    fs.writeFileSync(CONFIG.outputText, textReport);

    // Console summary
    console.log("=".repeat(55));
    console.log("📈 CONSOLIDATION SUMMARY\n");

    console.log(`🔀 MERGE: ${results.mergeRecommendations.length} groups`);
    for (const rec of results.mergeRecommendations.slice(0, 5)) {
        console.log(`   ${rec.canonical} ← ${rec.totalPages} pages`);
    }

    console.log(`\n🔄 REDIRECT: ${results.deleteRecommendations.length} groups`);
    for (const rec of results.deleteRecommendations.slice(0, 3)) {
        console.log(`   ${rec.canonical} ← ${rec.pagesToConsolidate.length} pages`);
    }

    console.log(`\n✏️ DIFFERENTIATE: ${results.differentiateRecommendations.length} groups`);

    console.log(`\n💾 Reports saved:`);
    console.log(`   ${CONFIG.outputReport}`);
    console.log(`   ${CONFIG.outputText}`);

    console.log("\n⚠️ NEXT STEPS:");
    console.log("   1. Review consolidation-plan.txt");
    console.log("   2. Manually merge/redirect pages as recommended");
    console.log("   3. Re-run overlap detector to verify");
}

main().catch(console.error);

#!/usr/bin/env node
/**
 * RockSEO Script 4 — Entity-Level Internal Link Weighting
 * 
 * Purpose:
 * - Builds entity graph across all pages
 * - Assigns link priority based on entity overlap
 * - Prevents random internal links
 * - Strengthens hub authority through semantic relationships
 * 
 * This is better than simple hub-spoke linking.
 * 
 * Usage: node rockseo/entity-link-weighting.mjs
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.join(__dirname, "..");

const CONFIG = {
    appDir: path.join(ROOT, "app/[locale]"),
    contentDirs: [
        "components/healthcare/services",
        "components/condition",
        "lib"
    ],
    extensions: [".tsx", ".ts"],
    outputReport: path.join(__dirname, "reports/entity-graph-report.json"),

    // Core dental entities for the clinic
    coreEntities: {
        // People
        "Dr. Rockson Samuel": { type: "person", weight: 10 },
        "dentist": { type: "role", weight: 5 },

        // Places
        "Indira Dental Clinic": { type: "organization", weight: 10 },
        "Vellore": { type: "location", weight: 8 },
        "Gandhi Nagar": { type: "location", weight: 5 },
        "Katpadi": { type: "location", weight: 5 },
        "Tamil Nadu": { type: "location", weight: 5 },

        // Treatments (high weight)
        "dental implants": { type: "treatment", weight: 9 },
        "implant": { type: "treatment", weight: 9 },
        "root canal": { type: "treatment", weight: 9 },
        "RCT": { type: "treatment", weight: 9 },
        "orthodontics": { type: "treatment", weight: 8 },
        "braces": { type: "treatment", weight: 8 },
        "invisalign": { type: "treatment", weight: 8 },
        "teeth whitening": { type: "treatment", weight: 7 },
        "dental crowns": { type: "treatment", weight: 7 },
        "veneers": { type: "treatment", weight: 7 },
        "gum treatment": { type: "treatment", weight: 8 },
        "tooth extraction": { type: "treatment", weight: 7 },

        // Conditions
        "toothache": { type: "condition", weight: 6 },
        "cavity": { type: "condition", weight: 6 },
        "gum disease": { type: "condition", weight: 6 },
        "gingivitis": { type: "condition", weight: 6 },
        "periodontitis": { type: "condition", weight: 6 },
        "bleeding gums": { type: "condition", weight: 6 },
        "sensitive teeth": { type: "condition", weight: 5 },
        "bad breath": { type: "condition", weight: 5 },

        // Features
        "CBCT": { type: "technology", weight: 7 },
        "digital X-ray": { type: "technology", weight: 6 },
        "laser": { type: "technology", weight: 7 },

        // Price signals
        "EMI": { type: "financial", weight: 5 },
        "Bajaj Finserv": { type: "financial", weight: 4 },
        "HDFC": { type: "financial", weight: 4 },
        "ICICI": { type: "financial", weight: 4 }
    }
};

const results = {
    timestamp: new Date().toISOString(),
    pagesAnalyzed: 0,
    entityGraph: {},
    pageEntities: {},
    linkRecommendations: [],
    hubPages: [],
    entityDistribution: {}
};

/**
 * Extract entities from content
 */
function extractEntities(content) {
    const contentLower = content.toLowerCase();
    const foundEntities = [];

    // Check for core entities
    for (const [entity, data] of Object.entries(CONFIG.coreEntities)) {
        const entityLower = entity.toLowerCase();
        if (contentLower.includes(entityLower)) {
            // Count occurrences
            const regex = new RegExp(entityLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
            const matches = content.match(regex) || [];

            foundEntities.push({
                entity,
                type: data.type,
                weight: data.weight,
                occurrences: matches.length
            });
        }
    }

    // Also extract bold text as potential entities
    const boldMatches = content.match(/\*\*([^*]+)\*\*/g) || [];
    for (const match of boldMatches) {
        const text = match.replace(/\*\*/g, "").trim();
        if (text.length > 3 && text.length < 50) {
            const existing = foundEntities.find(e =>
                e.entity.toLowerCase() === text.toLowerCase()
            );
            if (!existing) {
                foundEntities.push({
                    entity: text,
                    type: "highlighted",
                    weight: 3,
                    occurrences: 1
                });
            }
        }
    }

    return foundEntities;
}

/**
 * Calculate entity overlap score between two pages
 */
function calculateEntityOverlap(entities1, entities2) {
    let score = 0;
    const sharedEntities = [];

    for (const e1 of entities1) {
        for (const e2 of entities2) {
            if (e1.entity.toLowerCase() === e2.entity.toLowerCase()) {
                // Weight by entity importance and occurrence
                const entityScore = e1.weight * Math.min(e1.occurrences, 3);
                score += entityScore;
                sharedEntities.push(e1.entity);
            }
        }
    }

    return { score, sharedEntities };
}

/**
 * Get slug from file path
 */
function getSlug(filePath) {
    return filePath
        .replace(CONFIG.appDir, "")
        .replace("/page.tsx", "")
        .replace("/page.ts", "")
        .replace(ROOT + "/", "");
}

/**
 * Recursively get all page files
 */
function getPages(dir, list = []) {
    if (!fs.existsSync(dir)) return list;

    for (const f of fs.readdirSync(dir)) {
        const full = path.join(dir, f);
        const stat = fs.statSync(full);

        if (stat.isDirectory()) {
            if (!f.startsWith(".") && f !== "node_modules") {
                getPages(full, list);
            }
        } else if (CONFIG.extensions.includes(path.extname(f))) {
            list.push(full);
        }
    }
    return list;
}

/**
 * Main execution
 */
async function main() {
    console.log("🕸️ RockSEO Entity-Level Internal Link Weighting");
    console.log("=".repeat(55));
    console.log("\nBuilding entity graph for semantic link recommendations\n");

    // Collect all files
    const allFiles = [];
    allFiles.push(...getPages(CONFIG.appDir));
    for (const dir of CONFIG.contentDirs) {
        allFiles.push(...getPages(path.join(ROOT, dir)));
    }

    console.log(`📁 Files scanned: ${allFiles.length}`);

    // Extract entities from each file
    const pages = [];
    for (const file of allFiles) {
        try {
            const content = fs.readFileSync(file, "utf8");
            const entities = extractEntities(content);

            if (entities.length > 0) {
                const slug = getSlug(file);
                pages.push({
                    file,
                    slug,
                    entities,
                    entityCount: entities.length,
                    totalWeight: entities.reduce((sum, e) => sum + e.weight * e.occurrences, 0)
                });

                results.pageEntities[slug] = entities.map(e => e.entity);

                // Track entity distribution
                for (const e of entities) {
                    if (!results.entityDistribution[e.entity]) {
                        results.entityDistribution[e.entity] = { count: 0, pages: [] };
                    }
                    results.entityDistribution[e.entity].count++;
                    results.entityDistribution[e.entity].pages.push(slug);
                }
            }
        } catch (err) {
            // Skip files that can't be read
        }
    }

    results.pagesAnalyzed = pages.length;
    console.log(`📊 Pages with entities: ${pages.length}\n`);

    // Identify hub pages (high entity weight)
    const sortedByWeight = [...pages].sort((a, b) => b.totalWeight - a.totalWeight);
    results.hubPages = sortedByWeight.slice(0, 20).map(p => ({
        slug: p.slug,
        weight: p.totalWeight,
        entityCount: p.entityCount
    }));

    console.log("🏛️ Top Hub Pages (by entity weight):");
    for (const hub of results.hubPages.slice(0, 10)) {
        console.log(`   ${hub.slug} (weight: ${hub.weight}, entities: ${hub.entityCount})`);
    }

    // Calculate entity overlap between all page pairs
    console.log("\n🔄 Calculating entity relationships...");

    const linkScores = [];
    for (let i = 0; i < pages.length; i++) {
        for (let j = i + 1; j < pages.length; j++) {
            const overlap = calculateEntityOverlap(pages[i].entities, pages[j].entities);

            if (overlap.score >= 10 && overlap.sharedEntities.length >= 2) {
                linkScores.push({
                    from: pages[i].slug,
                    to: pages[j].slug,
                    score: overlap.score,
                    sharedEntities: overlap.sharedEntities
                });
            }
        }
    }

    // Sort by score and generate recommendations
    linkScores.sort((a, b) => b.score - a.score);

    // Build link recommendations (top links for each page)
    const pageLinks = {};
    for (const link of linkScores) {
        // Add to 'from' page
        if (!pageLinks[link.from]) pageLinks[link.from] = [];
        if (pageLinks[link.from].length < 5) {
            pageLinks[link.from].push({
                target: link.to,
                score: link.score,
                entities: link.sharedEntities.slice(0, 3)
            });
        }

        // Add to 'to' page (bidirectional)
        if (!pageLinks[link.to]) pageLinks[link.to] = [];
        if (pageLinks[link.to].length < 5) {
            pageLinks[link.to].push({
                target: link.from,
                score: link.score,
                entities: link.sharedEntities.slice(0, 3)
            });
        }
    }

    results.linkRecommendations = Object.entries(pageLinks).map(([page, links]) => ({
        page,
        recommendedLinks: links
    }));

    // Build entity graph for visualization
    const topEntities = Object.entries(results.entityDistribution)
        .sort((a, b) => b[1].count - a[1].count)
        .slice(0, 30);

    console.log("\n📊 Top Entities Across Site:");
    for (const [entity, data] of topEntities.slice(0, 15)) {
        console.log(`   ${entity}: ${data.count} pages`);
    }

    // Save report
    const reportDir = path.dirname(CONFIG.outputReport);
    if (!fs.existsSync(reportDir)) {
        fs.mkdirSync(reportDir, { recursive: true });
    }

    fs.writeFileSync(CONFIG.outputReport, JSON.stringify(results, null, 2));

    // Summary
    console.log("\n" + "=".repeat(55));
    console.log("📈 ENTITY GRAPH SUMMARY\n");
    console.log(`   Pages analyzed: ${results.pagesAnalyzed}`);
    console.log(`   Unique entities: ${Object.keys(results.entityDistribution).length}`);
    console.log(`   Link recommendations: ${results.linkRecommendations.length} pages`);
    console.log(`   Total relationship pairs: ${linkScores.length}`);

    console.log(`\n💾 Report saved: ${CONFIG.outputReport}`);

    console.log("\n✅ Entity graph complete. Use for semantic link building.");
}

main().catch(console.error);

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.join(__dirname, "../app"); // Point to app directory
const CONTENT_ROOT = path.join(__dirname, "../lib/data/blog-content-enhanced"); // Point to markdown blogs

const EXT = [".md", ".mdx", ".tsx", ".js", ".ts"];

function extractEntities(content, ext) {
    const entities = [];

    // Markdown style **bold**
    const boldMatches = [...content.matchAll(/\*\*(.*?)\*\*/g)].map(m => m[1]);
    entities.push(...boldMatches);

    // JSX/HTML style <strong>bold</strong>
    const strongMatches = [...content.matchAll(/<strong[^>]*>(.*?)<\/strong>/gs)].map(m => m[1]);
    entities.push(...strongMatches);

    return entities.map(e => e.trim()).filter(Boolean);
}

const pages = [];

function scan(dir) {
    if (!fs.existsSync(dir)) return;

    for (const f of fs.readdirSync(dir)) {
        const full = path.join(dir, f);
        if (fs.statSync(full).isDirectory()) {
            scan(full);
        } else if (EXT.includes(path.extname(f))) {
            const content = fs.readFileSync(full, "utf8");
            const entities = extractEntities(content, path.extname(f));

            // Only count pages that have entities (meaning they are content pages)
            if (entities.length > 0) {
                pages.push({
                    file: full,
                    relativePath: path.relative(path.join(__dirname, ".."), full),
                    entities
                });
            }
        }
    }
}

console.log("🔍 Scanning for entities in app and blog content...");
scan(ROOT);
scan(CONTENT_ROOT);

console.log(`✅ Scanned ${pages.length} pages containing entities.`);

const entityFrequency = {};
pages.forEach(p => {
    p.entities.forEach(e => {
        // Normalize entity (lowercase)
        const normalized = e.toLowerCase();
        entityFrequency[normalized] = (entityFrequency[normalized] || 0) + 1;
    });
});

const pageRank = pages.map(p => {
    let score = 0;
    p.entities.forEach(e => {
        const normalized = e.toLowerCase();
        score += entityFrequency[normalized] || 0;
    });
    return { file: p.relativePath, score };
});

pageRank.sort((a, b) => b.score - a.score);

// Output report
const REPORT_FILE = path.join(__dirname, "reports/entity-pagerank.txt");
const reportDir = path.dirname(REPORT_FILE);
if (!fs.existsSync(reportDir)) fs.mkdirSync(reportDir, { recursive: true });

const report = pageRank
    .map(p => `${p.file} → EntityRank: ${p.score}`)
    .join("\n");

fs.writeFileSync(REPORT_FILE, report);

console.log(`📈 Entity-based PageRank simulation complete.`);
console.log(`💾 Report saved to ${REPORT_FILE}`);

// Top 10 Hubs
console.log("\n🏆 Top 10 Authority Hubs:");
pageRank.slice(0, 10).forEach((p, i) => {
    console.log(`${i + 1}. ${p.file} (Score: ${p.score})`);
});

import fs from "fs";
import path from "path";

const MERGE_MAP = "rockseo/reports/merge-map.txt";
const OUTPUT = "rockseo/reports/redirects.txt";
const NEXT_OUTPUT = "rockseo/reports/nextjs-redirects.js";

if (!fs.existsSync(MERGE_MAP)) {
  console.error("❌ merge-map.txt not found");
  process.exit(1);
}

const lines = fs.readFileSync(MERGE_MAP, "utf8")
  .split("\n")
  .filter(Boolean);

const redirects = [];
const nextRedirects = [];

function toUrl(filePath) {
  // Normalize paths if they come as file paths vs URLs
  return filePath
    .replace("./app", "")
    .replace(".mdx", "")
    .replace(".md", "")
    .replace("/page", "") // Remove page if it exists
    .trim();
}

console.log(`🔄 Processing ${lines.length} merge entries...`);

lines.forEach(line => {
  // Expected format: "source_path → target_path"
  const parts = line.split(" → ");
  if (parts.length !== 2) return;

  const [left, right] = parts;
  const target = toUrl(right.trim());

  // Left side might be multiple sources separated by " + "
  left.split(" + ").forEach(src => {
    let from = toUrl(src.trim());
    let to = target;

    // Remove trailing slashes for comparison
    if (from.endsWith('/')) from = from.slice(0, -1);
    if (to.endsWith('/')) to = to.slice(0, -1);

    // Avoid self-redirects
    if (from === to) return;

    // Use original values for the rule, but we verified they aren't the same
    const finalFrom = toUrl(src.trim());
    const finalTo = target;

    // Double check exact match just in case
    if (finalFrom === finalTo) return;

    // Apache/Nginx Format
    redirects.push(`Redirect 301 ${finalFrom} ${finalTo}`);

    // Next.js Format
    nextRedirects.push(`
  {
    source: "${finalFrom}",
    destination: "${finalTo}",
    permanent: true
  }`);
  });
});

// Write generic redirects
fs.writeFileSync(OUTPUT, redirects.join("\n"));

// Write Next.js specific config
fs.writeFileSync(
  NEXT_OUTPUT,
  `// Paste inside next.config.js
module.exports = {
  async redirects() {
    return [${nextRedirects.join(",")}
    ]
  }
}`
);

console.log(`✅ Generated ${redirects.length} 301 redirect rules.`);
console.log(`💾 Generic rules: ${OUTPUT}`);
console.log(`💾 Next.js config: ${NEXT_OUTPUT}`);

