const fs = require('fs');
const path = require('path');

function walkDir(dir, callback) {
    fs.readdirSync(dir).forEach(f => {
        let dirPath = path.join(dir, f);
        let isDirectory = fs.statSync(dirPath).isDirectory();
        isDirectory ? walkDir(dirPath, callback) : callback(path.join(dir, f));
    });
}

function updatePaddingReplace(filePath) {
    if (!filePath.endsWith('.tsx')) return;

    let content = fs.readFileSync(filePath, 'utf8');
    let original = content;

    // Previous values in grep were:
    // pt-36 pb-48 lg:pt-48
    // pt-36 pb-16
    // pt-44 pb-32 lg:pt-56
    // pt-36 pb-32 lg:pt-48
    // pt-36 pb-40 lg:pt-48
    // pt-32 pb-20 lg:pt-48
    // pt-44 pb-20 lg:pt-52 (SubServiceTemplate)
    // pt-32 pb-56 (FAQ)
    // pt-32 pb-20 lg:pt-48 (Location Dept)

    content = content.replace(/pt-(32|36|40|44|48|52)\s+pb-([0-9]+)\s+lg:pt-[0-9]+/g, (match, p1, p2) => {
        return `pt-16 pb-${p2} lg:pt-24`;
    });

    // For ones without lg:pt
    content = content.replace(/pt-(32|36|40|44|48|52)\s+pb-([0-9]+)(\s|")/g, (match, p1, p2, p3) => {
        // Only replace if they don't have lg:pt right after (which should be caught by above, but just in case)
        if (match.includes('lg:pt')) return match;
        return `pt-16 pb-${p2}${p3}`;
    });

    if (content !== original) {
        fs.writeFileSync(filePath, content, 'utf8');
        console.log("Reduced padding in: " + filePath);
    }
}

walkDir('./src/app', updatePaddingReplace);
walkDir('./src/components', updatePaddingReplace);
console.log("Padding reduction complete.");

const fs = require('fs');
const path = require('path');

function walkDir(dir, callback) {
    fs.readdirSync(dir).forEach(f => {
        let dirPath = path.join(dir, f);
        let isDirectory = fs.statSync(dirPath).isDirectory();
        isDirectory ? walkDir(dirPath, callback) : callback(path.join(dir, f));
    });
}

function updatePaddingReplace(filePath) {
    if (!filePath.endsWith('.tsx')) return;

    let content = fs.readFileSync(filePath, 'utf8');
    let original = content;

    // We only want to bump pt- in large chunks that look like page heroes.
    // Usually they are: pt-36, pt-32, pt-44 combined with lg:pt-48, lg:pt-56 etc.
    // Let's explicitly target the combinations found in the grep.

    content = content.replace(/pt-36 pb-48 lg:pt-48/g, "pt-48 pb-48 lg:pt-60");
    content = content.replace(/pt-36 pb-16 overflow-hidden/g, "pt-48 pb-16 overflow-hidden");
    content = content.replace(/pt-44 pb-32 lg:pt-56/g, "pt-56 pb-32 lg:pt-64");
    content = content.replace(/pt-36 pb-32 lg:pt-48/g, "pt-48 pb-32 lg:pt-60");
    content = content.replace(/pt-36 pb-40 lg:pt-48/g, "pt-48 pb-40 lg:pt-60");
    content = content.replace(/pt-32 pb-20 lg:pt-48/g, "pt-44 pb-20 lg:pt-60");

    if (content !== original) {
        fs.writeFileSync(filePath, content, 'utf8');
        console.log("Updated padding in: " + filePath);
    }
}

walkDir('./src/app', updatePaddingReplace);
walkDir('./src/components', updatePaddingReplace);
console.log("Padding update complete.");

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

// Map of directory name to [display name, URL slug]
const DEPT_MAP = {
    'cardiology': ['Cardiology', 'cardiology'],
    'gastroenterology': ['Gastroenterology', 'gastroenterology'],
    'general-surgery': ['General Surgery', 'general-surgery'],
    'nephrology': ['Nephrology', 'nephrology'],
    'neurology': ['Neurology', 'neurology'],
    'obstetrics-gynaecology': ['Obstetrics & Gynaecology', 'obstetrics-gynaecology'],
    'oncology': ['Oncology', 'oncology'],
    'orthopaedics': ['Orthopaedics', 'orthopaedics'],
    'urology': ['Urology', 'urology'],
    'ent': ['ENT', 'ent'],
    'dermatology': ['Dermatology & Cosmetology', 'dermatology'],
    'paediatrics': ['Paediatrics', 'paediatrics'],
    'psychiatry': ['Psychiatry', 'psychiatry'],
};

const SERVICES_DIR = '/Users/rockson61/Downloads/Indira Hospital/src/app/services';

let fixed = 0;
let skipped = 0;

const depts = fs.readdirSync(SERVICES_DIR).filter(d =>
    fs.statSync(path.join(SERVICES_DIR, d)).isDirectory()
);

for (const dept of depts) {
    const deptPath = path.join(SERVICES_DIR, dept);
    const info = DEPT_MAP[dept];
    if (!info) {
        console.log(`SKIP (no mapping): ${dept}`);
        continue;
    }
    const [deptDisplayName, deptSlug] = info;

    const subs = fs.readdirSync(deptPath).filter(d =>
        fs.statSync(path.join(deptPath, d)).isDirectory()
    );

    for (const sub of subs) {
        const pageFile = path.join(deptPath, sub, 'page.tsx');
        if (!fs.existsSync(pageFile)) continue;

        let content = fs.readFileSync(pageFile, 'utf8');

        // Already has departmentName? skip
        if (content.includes('departmentName=')) {
            console.log(`SKIP (already has departmentName): ${dept}/${sub}`);
            skipped++;
            continue;
        }

        // Find <SubServiceTemplate and inject after it
        const marker = '<SubServiceTemplate';
        const idx = content.indexOf(marker);
        if (idx === -1) {
            console.log(`SKIP (no SubServiceTemplate): ${dept}/${sub}`);
            skipped++;
            continue;
        }

        // Insert departmentName and departmentSlug right after <SubServiceTemplate
        const insertAfter = idx + marker.length;
        const propsStr = `\n      departmentName="${deptDisplayName}"\n      departmentSlug="${deptSlug}"`;
        content = content.slice(0, insertAfter) + propsStr + content.slice(insertAfter);

        fs.writeFileSync(pageFile, content, 'utf8');
        console.log(`FIXED: ${dept}/${sub}`);
        fixed++;
    }
}

console.log(`\nDone: ${fixed} fixed, ${skipped} skipped`);

/**
 * Schema & SEO Migration Script V2
 * 
 * Adds missing SEO fields and metadata to Diagnostics, Health Packages, and Blog (Posts).
 */
import { createDirectus, rest, authentication, createField } from '@directus/sdk';
import dotenv from 'dotenv';
import path from 'path';

dotenv.config({ path: path.resolve(process.cwd(), '.env.local') });

const CMS_URL = process.env.NEXT_PUBLIC_API_URL;
const ADMIN_EMAIL = process.env.ADMIN_EMAIL;
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD;

if (!CMS_URL || !ADMIN_EMAIL || !ADMIN_PASSWORD) {
    console.error('Missing env vars. Ensure .env.local has NEXT_PUBLIC_API_URL, ADMIN_EMAIL, ADMIN_PASSWORD');
    process.exit(1);
}

const client = createDirectus(CMS_URL)
    .with(authentication('json', { autoRefresh: true }))
    .with(rest());

// =============================================
// HELPERS
// =============================================

async function addField(collection: string, field: string, config: any) {
    try {
        await client.request(createField(collection, {
            field,
            type: config.type,
            meta: {
                interface: config.interface || 'input',
                display: config.display || null,
                options: config.options || null,
                special: config.special || null,
                required: config.required || false,
                note: config.note || null,
                hidden: config.hidden || false,
                width: config.width || 'full',
            },
            schema: {
                is_unique: config.unique || false,
                default_value: config.default_value,
            }
        }));
        console.log(`    ✅ ${collection}.${field}`);
    } catch (e: any) {
        if (e?.errors?.[0]?.code === 'RECORD_NOT_UNIQUE' || e?.message?.includes('already exists')) {
            console.log(`    ⏭️  ${collection}.${field} (exists)`);
        } else {
            console.error(`    ❌ ${collection}.${field}: ${e?.errors?.[0]?.message || e?.message}`);
        }
    }
}

// =============================================
// MAIN SETUP
// =============================================

async function setup() {
