                </li>
              ))}
            </ul>
          )}

          {section.highlights && section.highlights.length > 0 && (
            <div className="grid gap-4 md:grid-cols-2">
              {section.highlights.map((highlight) => (
                <div key={highlight.title} className="rounded-xl bg-primary/10 p-5">
