            transition={{ duration: 0.8, delay, ease: [0.16, 1, 0.3, 1] }}
            className={`group relative flex flex-col items-center gap-6 bg-white dark:bg-white/10 backdrop-blur-xl dark:backdrop-blur-3xl rounded-[2.5rem] p-10 border border-slate-200 dark:border-white/20 hover:border-fuchsia-200 dark:hover:border-white/40 hover:bg-fuchsia-50/50 dark:hover:bg-white/15 transition-all duration-500 shadow-xl dark:shadow-2xl ${meta.glow} overflow-hidden`}
        >
            <div className="absolute inset-0 bg-gradient-to-br from-fuchsia-500/5 dark:from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

            <div className={`w-20 h-20 rounded-2xl bg-slate-50 dark:bg-white/5 ${meta.color} flex items-center justify-center group-hover:bg-fuchsia-500 group-hover:text-white transition-all duration-500 shadow-lg dark:shadow-xl group-hover:scale-110 z-10`}>
