const DEFAULTS = {
    services: { title: "Explore Our Treatments", subtitle: "Popular Services", href: "/doctor/near-me/treat" },
    treatments: { title: "Specific Procedures", subtitle: "Available Surgeries", href: "/doctor/near-me/treat" },
    doctors: { title: "Meet Our Specialists", subtitle: "Expert Doctors", href: "/doctors" },
    departments: { title: "Centres of Excellence", subtitle: "Departments", href: "/departments" },
    locations: { title: "We Serve Your Area", subtitle: "Our Locations", href: "/doctor/near-me" },
};

export async function InternalLinkGrid({
    type,
    title,
    subtitle,
    limit = 12,
    excludeSlug,
    parentSlug,
    className = "",
}: InternalLinkGridProps) {
    let items: { name: string; slug: string; url: string }[] = [];

    try {
        if (type === "services") {
            const data = await getServices().catch(() => []);
            items = data
                .filter((s: any) => s.slug !== excludeSlug)
                .slice(0, limit)
                .map((s: any) => ({ name: s.title || s.name, slug: s.slug, url: `/doctor/near-me/treat/${s.slug}` }));
        } else if (type === "treatments" && parentSlug) {
            const data = (await import("@/lib/data/treatment-data")).getAllTreatments();
            items = data
                .filter(t => t.parentServiceSlug === parentSlug && t.slug !== excludeSlug)
                .slice(0, limit)
                .map(t => ({ name: t.title, slug: t.slug, url: `/doctor/near-me/treat/${t.parentServiceSlug}/${t.slug}` }));
        } else if (type === "doctors") {
            const data = await getDoctors().catch(() => []);
            items = data
                .filter((d: any) => d.slug !== excludeSlug)
                .slice(0, limit)
                .map((d: any) => {
                    const dept = typeof d.department === 'string' ? d.department : d.department?.name || d.specialty || 'specialist';
                    const specialtySlug = dept.toLowerCase().replace(/[^a-zA-Z0-9]+/g, '-').replace(/(^-|-$)/g, '');
                    return { name: d.name, slug: d.slug, url: `/doctor/${specialtySlug}/${d.slug}` };
                });
        } else if (type === "departments") {
            const data = await getDepartments().catch(() => []);
            items = data
                .filter((d: any) => d.slug !== excludeSlug)
                .slice(0, limit)
                .map((d: any) => ({ name: d.title || d.name, slug: d.slug, url: `/departments/${d.slug}` }));
        } else if (type === "locations") {
            items = tamilNaduLocations
                .filter(l => l.slug !== excludeSlug)
                .slice(0, limit)
                .map(l => ({ name: l.name, slug: l.slug, url: `/doctor/near-me/${l.slug}` }));
        }
    } catch {
        return null;
    }

    if (!items.length) return null;

    const Icon = ICONS[type];
    const colors = COLORS[type];
    const defaults = DEFAULTS[type];
    const displayTitle = title || defaults.title;
    const displaySubtitle = subtitle || defaults.subtitle;

    return (
        <section className={`py-20 ${className}`}>
            <SectionContainer>
                <div className="text-center mb-12">
                    <span className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 mb-3 block">
                        {displaySubtitle}
                    </span>
                    <h2 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight">
                        {displayTitle}
                    </h2>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
                    {items.map((item) => (
                        <Link
                            key={item.slug}
                            href={item.url}
                            className={`group flex items-center gap-3 px-4 py-3.5 rounded-xl border text-sm font-bold transition-all hover:-translate-y-0.5 hover:shadow-md ${colors}`}
                        >
                            <Icon className="w-4 h-4 flex-shrink-0 opacity-60 group-hover:opacity-100 transition-opacity" />
                            <span className="truncate text-slate-700 dark:text-slate-300 group-hover:text-slate-900 dark:group-hover:text-white">{item.name}</span>
                        </Link>
                    ))}
                </div>

                <div className="mt-8 text-center">
                    <Link
                        href={defaults.href}
                        className="inline-flex items-center gap-2 text-sm font-black text-fuchsia-600 hover:text-fuchsia-700 uppercase tracking-widest transition-colors"
                    >
                        View All {displaySubtitle}
                        <ArrowRight className="w-4 h-4" />
                    </Link>
                </div>
            </SectionContainer>
        </section>
    );
}

import { siteConfig } from "@/config/site";

type SchemaType = "hospital" | "itemList" | "physician" | "breadcrumb";

interface HospitalSchemaProps {
    type: "hospital";
}

interface ItemListSchemaProps {
    type: "itemList";
    name: string;
    items: { name: string; url: string }[];
}

interface PhysicianSchemaProps {
    type: "physician";
    name: string;
    specialty: string;
    description: string;
    url: string;
}

interface BreadcrumbSchemaProps {
    type: "breadcrumb";
    items: { name: string; url: string }[];
}

interface MedicalProcedureSchemaProps {
    type: "medicalProcedure";
    name: string;
    description: string;
    url: string;
    preparation?: string;
}

type JsonLdSchemaProps = HospitalSchemaProps | ItemListSchemaProps | PhysicianSchemaProps | BreadcrumbSchemaProps | MedicalProcedureSchemaProps;

export function JsonLdSchema(props: JsonLdSchemaProps) {
    let schema: Record<string, any>;

    if (props.type === "hospital") {
        schema = {
            "@context": "https://schema.org",
            "@type": ["Hospital", "MedicalBusiness"],
            name: siteConfig.name,
            url: siteConfig.url,
            description: siteConfig.description,
            telephone: siteConfig.contact.phone,
            address: {
                "@type": "PostalAddress",
                streetAddress: "Vellore",
                addressLocality: "Vellore",
                addressRegion: "Tamil Nadu",
                postalCode: "632001",
                addressCountry: "IN",
            },
            geo: {
                "@type": "GeoCoordinates",
                latitude: "12.9165",
                longitude: "79.1325",
            },
            medicalSpecialty: [
                "Cardiology", "General Surgery", "Laparoscopic Surgery",
                "Urology", "Proctology", "Orthopedics", "ENT",
                "Gynaecology", "Ophthalmology", "Dermatology",
            ],
            availableService: {
                "@type": "MedicalProcedure",
                name: "Multi-Speciality Healthcare Services",
            },
            openingHoursSpecification: {
                "@type": "OpeningHoursSpecification",
                dayOfWeek: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
                opens: "00:00",
                closes: "23:59",
            },
        };
    } else if (props.type === "itemList") {
        schema = {
            "@context": "https://schema.org",
            "@type": "ItemList",
            name: props.name,
            numberOfItems: props.items.length,
            itemListElement: props.items.map((item, i) => ({
                "@type": "ListItem",
                position: i + 1,
                name: item.name,
                url: `${siteConfig.url}${item.url}`,
            })),
        };
    } else if (props.type === "physician") {
        schema = {
            "@context": "https://schema.org",
            "@type": "Physician",
            name: props.name,
            medicalSpecialty: props.specialty,
            description: props.description,
            url: `${siteConfig.url}${props.url}`,
            worksFor: {
                "@type": "Hospital",
                name: siteConfig.name,
                url: siteConfig.url,
            },
        };
    } else if (props.type === "medicalProcedure") {
        schema = {
            "@context": "https://schema.org",
            "@type": "MedicalProcedure",
            name: props.name,
            description: props.description,
            url: `${siteConfig.url}${props.url}`,
            provider: {
                "@type": "Hospital",
                name: siteConfig.name,
                url: siteConfig.url,
            },
            ...(props.preparation && { bodyLocation: props.preparation }),
        };
    } else {
        schema = {
            "@context": "https://schema.org",
            "@type": "BreadcrumbList",
            itemListElement: props.items.map((item, i) => ({
                "@type": "ListItem",
                position: i + 1,
                name: item.name,
                item: `${siteConfig.url}${item.url}`,
            })),
        };
    }

    return (
        <script
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
        />
    );
}

import Link from "next/link";
import { ArrowRight, MapPin, Users, Layers } from "lucide-react";
import { Stethoscope } from "healthicons-react/outline";
import { getServices, getDoctors, getDepartments } from "@/lib/api";
import { tamilNaduLocations } from "@/lib/data/tamilnadu-locations";
import { SectionContainer } from "@/components/ui/section-container";
import { DoctorCard } from "@/components/entities/DoctorCard";
import { ServiceCard } from "@/components/entities/ServiceCard";
import { DepartmentCard } from "@/components/entities/DepartmentCard";
import { LocationCard } from "@/components/entities/LocationCard";

interface UnifiedEntitySectionProps {
    type: "services" | "doctors" | "departments" | "locations" | "treatments";
    title?: string;
    subtitle?: string;
    featuredLimit?: number; // How many large rich cards to show (e.g. 4 or 6)
    linkLimit?: number;     // How many small links to show after the cards (e.g. 12 or 24)
    excludeSlug?: string;
    parentSlug?: string;    // specifically for 'treatments' type
    className?: string;
}

const ICONS = {
    services: Stethoscope,
    treatments: Stethoscope,
    doctors: Users,
    departments: Layers,
    locations: MapPin,
};

const COLORS = {
    services: "text-fuchsia-600 dark:text-fuchsia-400 bg-fuchsia-50 dark:bg-fuchsia-950/30 border-fuchsia-100 dark:border-fuchsia-900/50 hover:border-fuchsia-300 dark:hover:border-fuchsia-700",
    treatments: "text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/30 border-emerald-100 dark:border-emerald-900/50 hover:border-emerald-300 dark:hover:border-emerald-700",
    doctors: "text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-950/30 border-blue-100 dark:border-blue-900/50 hover:border-blue-300 dark:hover:border-blue-700",
    departments: "text-violet-600 dark:text-violet-400 bg-violet-50 dark:bg-violet-950/30 border-violet-100 dark:border-violet-900/50 hover:border-violet-300 dark:hover:border-violet-700",
    locations: "text-amber-600 dark:text-amber-500 bg-amber-50 dark:bg-amber-950/30 border-amber-100 dark:border-amber-900/50 hover:border-amber-300 dark:hover:border-amber-700",
};

const DEFAULTS: Record<string, { title: string; subtitle: string; href: string }> = {
    services: { title: "Explore Our Treatments", subtitle: "Popular Services", href: "/doctor/near-me/treat" },
    treatments: { title: "Specific Procedures", subtitle: "Available Surgeries", href: "/doctor/near-me/treat" },
    doctors: { title: "Meet Our Specialists", subtitle: "Expert Doctors", href: "/doctors" },
    departments: { title: "Centres of Excellence", subtitle: "Our Departments", href: "/departments" },
    locations: { title: "We Serve Your Area", subtitle: "Our Locations", href: "/doctor/near-me" },
};

export async function UnifiedEntitySection({
    type,
    title,
    subtitle,
    featuredLimit = 6,
    linkLimit = 16,
    excludeSlug,
    parentSlug,
    className = "",
}: UnifiedEntitySectionProps) {
    const defaults = DEFAULTS[type];
    const displayTitle = title || defaults.title;
    const displaySubtitle = subtitle || defaults.subtitle;
    const Icon = ICONS[type];
    const colors = COLORS[type];

    let allItems: any[] = [];

    // 1. Fetch Master Data
    try {
        if (type === "services") {
            const data = await getServices().catch(() => []);
            allItems = data.filter((s: any) => s.slug !== excludeSlug);
        } else if (type === "treatments" && parentSlug) {
            const data = (await import("@/lib/data/treatment-data")).getAllTreatments();
            allItems = data.filter(t => t.parentServiceSlug === parentSlug && t.slug !== excludeSlug);
        } else if (type === "doctors") {
            const data = await getDoctors().catch(() => []);
            allItems = data.filter((d: any) => d.slug !== excludeSlug);
        } else if (type === "departments") {
            const data = await getDepartments().catch(() => []);
            allItems = data.filter((d: any) => d.slug !== excludeSlug);
        } else if (type === "locations") {
            allItems = tamilNaduLocations.filter(l => l.slug !== excludeSlug);
        }
    } catch {
        return null;
    }

    if (!allItems.length) return null;

    // 2. Split Data: Featured Cards vs. Remaining Links
    // Note: 'treatments' type doesn't have a large UI card variant historically, so we treat it all as links if needed, 
    // or just pass 0 to featuredLimit when calling it.
    const featuredItems = allItems.slice(0, featuredLimit);
    const linkItems = allItems.slice(featuredLimit, featuredLimit + linkLimit).map((item: any) => {
        let name = item.title || item.name;
        let url = "";

        if (type === "services") url = `/doctor/near-me/treat/${item.slug}`;
        else if (type === "treatments") url = `/doctor/near-me/treat/${item.parentServiceSlug}/${item.slug}`;
        else if (type === "doctors") {
            const dept = typeof item.department === 'string' ? item.department : item.department?.name || item.specialty || 'specialist';
            const specialtySlug = dept.toLowerCase().replace(/[^a-zA-Z0-9]+/g, '-').replace(/(^-|-$)/g, '');
            url = `/doctor/${specialtySlug}/${item.slug}`;
        }
        else if (type === "departments") url = `/departments/${item.slug}`;
        else if (type === "locations") url = `/doctor/near-me/${item.slug}`;

        return { name, slug: item.slug, url };
    });

    let FeaturedContent: React.ReactNode = null;

    // 3. Render Large Cards
    if (featuredItems.length > 0) {
        if (type === "services") {
            FeaturedContent = (
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                    {featuredItems.map((s: any) => <ServiceCard key={s.slug || s.id} service={s} variant="detail" />)}
                </div>
            );
        } else if (type === "doctors") {
            FeaturedContent = (
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                    {featuredItems.map((d: any) => <DoctorCard key={d.slug || d.id} doctor={d} variant="grid" />)}
                </div>
            );
        } else if (type === "departments") {
            FeaturedContent = (
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                    {featuredItems.map((d: any) => <DepartmentCard key={d.slug || d.id} department={d} variant="grid" />)}
                </div>
            );
        } else if (type === "locations") {
            FeaturedContent = (
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                    {featuredItems.map((l: any) => <LocationCard key={l.slug} location={l} variant="compact" />)}
                </div>
            );
        }
    }

    // 4. Render Layout
    return (
        <section className={`py-20 ${className}`}>
            <SectionContainer>
                {/* Unified Header */}
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12">
                    <div>
                        <span className="text-xs font-black uppercase tracking-[0.2em] text-fuchsia-600 dark:text-fuchsia-400 mb-3 flex items-center gap-2">
                            <Icon className="w-4 h-4" /> {displaySubtitle}
                        </span>
                        <h2 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight">
                            {displayTitle}
                        </h2>
                    </div>
                    <Link
                        href={defaults.href}
                        className="group flex items-center gap-2 text-sm font-black text-fuchsia-600 hover:text-fuchsia-700 dark:text-fuchsia-400 dark:hover:text-fuchsia-300 uppercase tracking-widest transition-colors"
                    >
                        View All <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                    </Link>
                </div>

                {/* Top: Rich Cards */}
                {FeaturedContent}

                {/* Bottom: SEO Link Grid (Only if remaining items exist) */}
                {linkItems.length > 0 && (
                    <div className="mt-8">
                        <h3 className="text-sm font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-6 flex items-center gap-2">
                            <ArrowRight className="w-4 h-4" /> Also Explore {displayTitle}
                        </h3>
                        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
                            {linkItems.map((item) => (
                                <Link
                                    key={item.slug}
                                    href={item.url}
                                    className={`group flex items-center gap-3 px-4 py-3.5 rounded-xl border text-sm font-bold transition-all hover:-translate-y-0.5 hover:shadow-md ${colors}`}
                                >
                                    <Icon className="w-4 h-4 flex-shrink-0 opacity-60 group-hover:opacity-100 transition-opacity" />
                                    <span className="truncate text-slate-700 dark:text-slate-300 group-hover:text-slate-900 dark:group-hover:text-white">{item.name}</span>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </SectionContainer>
        </section>
    );
}

