export function SeverityQuiz() {
    const [step, setStep] = useState(0);
    const [score, setScore] = useState(0);
    const [showResult, setShowResult] = useState(false);

    const handleAnswer = (optionScore: number) => {
        const newScore = score + optionScore;
        setScore(newScore);

        if (step < QUESTIONS.length - 1) {
            setStep(step + 1);
        } else {
            setShowResult(true);
        }
    };

    const getResult = () => {
        if (score <= 2) return {
            grade: "Grade I (Mild)",
            advice: "Likely manageable with diet & medication.",
            color: "text-green-600",
            bg: "bg-green-50"
        };
        if (score <= 5) return {
            grade: "Grade II (Moderate)",
            advice: "May require non-invasive Laser treatment.",
            color: "text-yellow-600",
            bg: "bg-yellow-50"
        };
        return {
            grade: "Grade III/IV (Severe)",
            advice: "Surgical intervention highly recommended.",
            color: "text-red-600",
            bg: "bg-red-50"
        };
    };

    const resultData = getResult();

    return (
        <Card className="max-w-md mx-auto overflow-hidden bg-white dark:bg-slate-900 shadow-lg border-2 border-primary-100">
            <div className="bg-primary-600 p-4 text-white text-center">
                <h3 className="font-bold text-lg">Piles Severity Check</h3>
                <p className="text-primary-100 text-xs">Answer 3 simple questions to know your stage.</p>
            </div>

            <div className="p-6">
                {!showResult ? (
                    <>
                        <div className="flex justify-between text-xs text-gray-400 mb-2">
                            <span>Question {step + 1} of {QUESTIONS.length}</span>
                            <span>{Math.round(((step) / QUESTIONS.length) * 100)}%</span>
                        </div>
                        <div className="w-full bg-gray-100 h-1.5 rounded-full mb-6 overflow-hidden">
                            <div className="bg-primary-500 h-full transition-all duration-300" style={{ width: `${((step + 1) / QUESTIONS.length) * 100}%` }}></div>
                        </div>

                        <h4 className="text-lg font-medium text-gray-900 dark:text-white mb-6">{QUESTIONS[step].text}</h4>

                        <div className="space-y-3">
                            {QUESTIONS[step].options.map((opt, i) => (
                                <button
                                    key={i}
                                    onClick={() => handleAnswer(opt.score)}
                                    className="w-full text-left p-4 rounded-xl border border-gray-200 dark:border-slate-700 hover:border-primary-500 hover:bg-primary-50 transition-all flex justify-between group"
                                >
                                    <span className="text-gray-700 dark:text-gray-300 font-medium group-hover:text-primary-700">{opt.label}</span>
                                    <ArrowRight className="w-5 h-5 text-gray-300 group-hover:text-primary-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                                </button>
                            ))}
                        </div>
                    </>
                ) : (
                    <div className="text-center animate-in fade-in zoom-in duration-300">
                        <div className={cn("mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4", resultData.bg, resultData.color)}>
                            <AlertTriangle className="w-8 h-8" />
                        </div>

                        <p className="text-gray-500 dark:text-gray-400 uppercase tracking-widest text-xs font-bold mb-2">Your Result</p>
                        <h2 className={cn("text-2xl font-bold mb-2", resultData.color)}>{resultData.grade}</h2>
                        <p className="text-gray-600 dark:text-gray-400 mb-8">{resultData.advice}</p>

                        <Button size="lg" className="w-full animate-bounce">
                            Consult a Doctor Now
                        </Button>
                        <p className="text-xs text-gray-400 mt-4">
                            *This tool provides an indication only and is not a medical diagnosis.
                        </p>
                    </div>
                )}
            </div>
        </Card>
    );
}

import { getFaqsByEntity } from "@/lib/api";
import { FAQSection } from "./FAQSection";
import { cn } from "@/lib/utils";

interface EntityFAQsProps {
    entityType: string;
    entityName: string;
    entitySlug?: string;
    title?: string;
    description?: string;
    className?: string;
}

/**
 * EntityFAQs - A universal server component to fetch and display 
 * SEO-optimized FAQs for any entity (Doctor, Service, Department, etc.)
 */
export default async function EntityFAQs({
    entityType,
    entityName,
    entitySlug,
    title,
    description,
    className
}: EntityFAQsProps) {
    const faqs = await getFaqsByEntity(entityType, entityName);

    if (!faqs || faqs.length === 0) {
        return null; // Don't render if no FAQs available
    }

    return (
        <section className={cn("bg-[#FAFAFA] dark:bg-slate-950 py-16 px-6 lg:px-8 border-t border-slate-100 dark:border-slate-700", className)}>
            <div className="max-w-7xl mx-auto">
                <FAQSection
                    title={title || `Frequently Asked Questions about ${entityName}`}
                    description={description || `Find answers to common questions about ${entityName} at Indira Super Speciality Hospital.`}
                    faqs={faqs.map((f: any) => ({ question: f.question, answer: f.answer }))}
                    category={entityType}
                />
            </div>
        </section>
    );
}

